const attendees: readonly [string, string, string, Role][] = [["CM", "Collin Manyande", "OAK-2026-1042-QPLA", "Partner"], ["JO", "James Odhiambo", "OAK-2026-2218-NKRT", "OAK Staff"], ["AD", "Awa Diallo", "OAK-2026-7842-XKPH", "Partner"], ["KM", "Kayden Mamu", "OAK-2026-4491-WJQS", "Presenter"]];
export default function CheckInPage() { const [success, setSuccess] = useState(false); const [selected, setSelected] = useState(attendees[0]); return <Frame role="Coordination Team" dark><main className="mx-auto max-w-4xl px-5 py-10 text-white"><Title eyebrow="Coordination desk" title="Check in attendees" description="Scan a digital pass or choose a simulation below to test the check-in flow." /><div className="grid gap-6 lg:grid-cols-[1fr_1fr]"><section><div className="relative aspect-[4/3] overflow-hidden rounded-3xl bg-[#111827] ring-1 ring-white/10"><span className="corner corner-tl" /><span className="corner corner-tr" /><span className="corner corner-bl" /><span className="corner corner-br" /><div className="absolute inset-0 grid place-items-center"><div className="text-center"><div className="mx-auto mb-5 h-16 w-16 rounded-full border border-emerald-400/40 bg-emerald-400/10" /><p className="text-sm font-semibold">Position QR code within the frame</p><p className="mt-2 text-xs text-white/45">Hold camera steady · Auto-scans in 1–2 seconds</p></div></div></div><div className="mt-5 rounded-2xl bg-[#111827] p-5"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-white/45">Manual code entry</p><div className="mt-3 flex gap-2"><input placeholder="OAK-2026-XXXX-XXXX" className="min-w-0 flex-1 rounded-xl border border-white/10 bg-white/5 px-4 py-3 text-sm outline-none focus:border-emerald-500" /><button onClick={() => setSuccess(true)} className="rounded-xl bg-emerald-500 px-5 text-sm font-bold text-slate-950">Check</button></div></div></section><section><p className="mb-4 text-[10px] font-bold uppercase tracking-[.2em] text-white/45">Simulate QR scan</p><div className="space-y-3">{attendees.map((attendee) => <button key={attendee[1]} onClick={() => { setSelected(attendee); setSuccess(true); }} className="flex w-full items-center gap-3 rounded-2xl bg-white/5 p-4 text-left ring-1 ring-white/10 transition hover:bg-white/10"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-emerald-400/15 text-xs font-bold text-emerald-300">{attendee[0]}</span><span className="min-w-0 flex-1"><strong className="block text-sm">{attendee[1]}</strong><span className="block truncate font-mono text-[10px] text-white/40">{attendee[2]}</span></span><Badge role={attendee[3]}>{attendee[3]}</Badge></button>)}</div></section></div></main>{success && <div className="fixed inset-0 z-30 grid place-items-center bg-[#0d131f]/90 p-5"><div className="w-full max-w-md rounded-3xl bg-white p-7 text-slate-900 shadow-2xl"><div className="flex items-center justify-between"><span className="grid h-12 w-12 place-items-center rounded-full bg-emerald-100 text-xl text-emerald-700">✓</span><button onClick={() => setSuccess(false)} className="text-2xl text-slate-400">×</button></div><p className="mt-6 text-xs font-bold uppercase tracking-wider text-emerald-600">Checked in successfully</p><h2 className="mt-2 text-2xl font-bold">{selected[1]}</h2><p className="mt-1 text-sm text-slate-500">{selected[2]}</p><div className="mt-6 grid grid-cols-2 gap-4 rounded-2xl bg-slate-50 p-4 text-sm"><div><p className="text-[10px] font-bold uppercase text-slate-400">Next session</p><p className="mt-1 font-semibold">Opening Plenary</p></div><div><p className="text-[10px] font-bold uppercase text-slate-400">Venue</p><p className="mt-1 font-semibold">Main Hall A</p></div></div><p className="mt-5 text-xs text-slate-500">74 of 110 attendees checked in</p><div className="mt-2 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full w-[67%] rounded-full bg-emerald-500" /></div><Link href="/admin/check-in" onClick={() => setSuccess(false)} className="mt-7 block rounded-xl bg-slate-900 px-5 py-3 text-center text-sm font-bold text-white">Scan next attendee</Link></div></div>}</Frame>; }
